      { t: 2.3, p: { x: -1.15, y: 1.05, z: -0.85 }, v: { x: 0.55, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
      { t: 4.7, p: { x: 0.15, y: 1.40, z: 0.25 }, v: { x: 0.55, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
